struct Circle {
    double area() const { return 3.0; }
};

struct Square {
    double area() const { return 4.0; }
};

struct Triangle {
    double area() const { return 2.0; }
};

template <typename T>
double measure(const T& shape) { return shape.area(); }

template <typename T>
double report(const T& shape) { return shape.area(); }

template <typename T>
struct Box {
    double area() const { return 1.0; }
};

template <typename T>
double size_of(const Box<T>& box) { return box.area(); }

template <typename T>
struct Crate {
    static constexpr int capacity = 1;
};

template <typename T>
int load() { return Crate<T>::capacity; }

struct Polygon {
    virtual int sides() const { return 0; }
};

struct Hexagon : Polygon {
    int sides() const override { return 6; }
};

template <typename T>
int count(const T& shape) { return shape.sides(); }

double scale(double value) { return value * 2; }

template <typename T>
double grow(const T& value) { return scale(value); }

int main() {
    return static_cast<int>(measure(Circle{}) + report(Square{}) + report(Triangle{})) +
           count(Polygon{}) + count(Hexagon{}) + load<int>();
}

